<div id="admin-requests-panel" class="admin-panel" role="tabpanel" aria-labelledby="tab-requests" hidden>
                        <div class="panel-header"><div><p class="eyebrow">Document services</p><h2>Requests queue</h2><p>Review and update resident document requests.</p></div></div>
                        <div class="request-table-controls"><label class="visually-hidden" for="admin-request-search">Search by tracking number or resident name</label><input id="admin-request-search" type="search" placeholder="Search tracking number or resident name" data-action-input="filterAdminRequests()"><div class="request-status-tabs" role="toolbar" aria-label="Filter requests by status"><button type="button" class="request-filter active" data-filter-status="All" data-filter-label="All" aria-pressed="true" data-action-click="setAdminRequestFilter('All', this)">All (0)</button><button type="button" class="request-filter" data-filter-status="Pending" data-filter-label="Pending" aria-pressed="false" data-action-click="setAdminRequestFilter('Pending', this)">Pending (0)</button><button type="button" class="request-filter" data-filter-status="Approved" data-filter-label="Approved" aria-pressed="false" data-action-click="setAdminRequestFilter('Approved', this)">Approved (0)</button><button type="button" class="request-filter" data-filter-status="Ready for Pickup" data-filter-label="Ready for pickup" aria-pressed="false" data-action-click="setAdminRequestFilter('Ready for Pickup', this)">Ready for pickup (0)</button><button type="button" class="request-filter" data-filter-status="Completed" data-filter-label="Completed" aria-pressed="false" data-action-click="setAdminRequestFilter('Completed', this)">Completed (0)</button><button type="button" class="request-filter" data-filter-status="Rejected" data-filter-label="Rejected" aria-pressed="false" data-action-click="setAdminRequestFilter('Rejected', this)">Rejected (0)</button></div></div>
                        <div class="card full-width-card table-card admin-table-scroll request-admin-table-wrap"><table class="admin-table request-admin-table"><caption class="visually-hidden">Resident document requests</caption><thead><tr><th scope="col">Tracking</th><th scope="col">Resident</th><th scope="col">Document</th><th scope="col">Requested</th><th scope="col">Status</th><th scope="col">Payment</th><th scope="col">Actions</th></tr></thead><tbody id="admin-request-list"></tbody></table></div>
                        <div id="admin-request-mobile-list" class="admin-request-mobile-list" aria-live="polite"></div>
                        <nav class="activity-pagination request-pagination" aria-label="Request pages"><span id="request-page-status">Page 1</span><div><button class="btn-outline" type="button" id="request-prev" data-action-click="changeAdminRequestPage(-1)" disabled>Previous</button><button class="btn-outline" type="button" id="request-next" data-action-click="changeAdminRequestPage(1)" disabled>Next</button></div></nav>
                    </div>
                    <section id="admin-request-detail-panel" class="admin-panel admin-request-detail-panel" aria-labelledby="request-detail-title" hidden>
                        <button class="back-link request-detail-back" type="button" data-action-click="closeAdminRequestDetail()"><i class="fas fa-arrow-left" aria-hidden="true"></i> Back to requests</button>
                        <div id="request-detail-content"><p class="empty-state">Choose a request to view its details.</p></div>
                    </section>
                    
